beforeExample:
class Test {
    void example() {
        Object x = null;
        System.out.println(x);
    }
}

afterExample:
class Test {
    void example() {
        Object x;
        x = null;
        System.out.println(x);
    }
}

negativeExample:
class Test {
    void example() {
        Object y = new Object(); // Should not match: initializer is not null literal
        String s = "hello"; // Should not match: initializer is not null literal
        System.out.println(y + s);
    }
}
